function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : ((r & 0x3) | 0x8);
    return v.toString(16);
  });
}
return $input.all().map((item) => ({json: {...item.json, p2_submission_key: uuidv4(), p2_model_name: 'google/gemma-4-12b-qat', p2_detection_prompt_version: 'phase2-main-issue-detection-v3-centrality', p2_safeguard_prompt_version: 'phase2-main-issue-safeguard-v4-causal-grounding'}}));

